<script setup lang="ts">
import { t as tr } from '../../i18n';

import { onMounted, ref } from 'vue';
import { api } from '../../api/client';
import type { components } from '../../api/generated/admin';
const cfg=ref<components['schemas']['ConsumerIdentitySettings']>();const flags=ref({smtp_password_set:false,github_secret_set:false,linuxdo_secret_set:false});
const clearSMTP=ref(false),clearGitHub=ref(false),clearLinuxDO=ref(false),busy=ref(false),error=ref(''),message=ref('');
async function load(){const d=await api('/admin/api/consumer/identity');cfg.value=d.settings;if(!cfg.value.smtp_port)cfg.value.smtp_port=587;flags.value=d;}
async function save(){if(!cfg.value||busy.value)return;busy.value=true;error.value='';message.value='';try{await api('/admin/api/consumer/identity',{method:'POST',body:{settings:cfg.value,clear_smtp:clearSMTP.value,clear_github:clearGitHub.value,clear_linuxdo:clearLinuxDO.value}});await load();clearSMTP.value=clearGitHub.value=clearLinuxDO.value=false;message.value=tr('登录配置已保存');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>error.value=(e as Error).message));
</script>
<template><div class="consumer-form"><h3>{{tr('邮件与第三方登录')}}</h3><p class="hint">{{tr('第三方登录与邮件配置。第三方账号需先在个人资料中绑定；不自动注册或按邮箱合并账号。')}}</p><form v-if="cfg" @submit.prevent="save"><div class="field"><label>{{tr('公开访问地址')}}<input v-model="cfg.public_origin" placeholder="https://panel.example.com" type="url"></label><p class="hint">{{tr('第三方应用回调地址：公开访问地址 + /auth/oauth/callback。反向代理时需正确传递 HTTPS。')}}</p></div>
<h4>{{tr('邮件服务')}}</h4><div class="field-grid cols-2"><div class="field"><label>{{tr('SMTP 主机')}}<input v-model="cfg.smtp_host" placeholder="smtp.example.com"></label></div><div class="field"><label>{{tr('SMTP 端口')}}<input v-model.number="cfg.smtp_port" type="number" min="1" max="65535" :placeholder="tr('465 或 587')"></label></div><div class="field"><label>{{tr('SMTP 用户')}}<input v-model="cfg.smtp_user" autocomplete="off"></label></div><div class="field"><label>{{tr('SMTP 密码')}}<input v-model="cfg.smtp_password" type="password" autocomplete="new-password" :placeholder="flags.smtp_password_set?tr('已保存，留空保留'):tr('未设置')"></label></div><div class="field"><label>{{tr('发件邮箱')}}<input v-model="cfg.smtp_from" type="email"></label></div></div><label class="check"><input v-model="clearSMTP" type="checkbox">{{tr('清除已保存 SMTP 密码')}}</label><p class="hint">{{tr('使用 TLS / STARTTLS；填写后提供邮箱验证和密码找回。留空 SMTP 主机关闭邮件功能。')}}</p>
<template v-for="provider in (['github','linuxdo'] as const)" :key="provider"><h4>{{provider==='github'?'GitHub':'LinuxDO'}}</h4><label class="check"><input v-model="cfg[provider].enabled" type="checkbox">{{tr('启用登录与绑定')}}</label><div class="field-grid cols-2"><div class="field"><label>Client ID<input v-model="cfg[provider].client_id" autocomplete="off"></label></div><div class="field"><label>Client Secret<input v-model="cfg[provider].client_secret" type="password" autocomplete="new-password" :placeholder="tr('留空保留已保存值')"></label></div></div></template>
<label class="check"><input v-model="clearGitHub" type="checkbox">{{tr('清除 GitHub Secret')}}</label><label class="check"><input v-model="clearLinuxDO" type="checkbox">{{tr('清除 LinuxDO Secret')}}</label><button class="btn primary" :disabled="busy">{{tr('保存登录配置')}}</button></form><p v-if="error" class="err-text" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p></div></template>
